import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`linkedin-audit`,heroTitle:`Optimize your LinkedIn profile in minutes`,heroSubtitle:`Perplexity Computer audits your headline, summary, and experience against recruiter search patterns, then rewrites underperforming sections — automatically.`,inputUrlCta:`Audit my profile`,inputUrlPlaceholder:`linkedin.com/in/you`,inputUrlPrefill:`Go to {url} and run a full LinkedIn profile audit. (1) Evaluate the headline for keyword density, recruiter search alignment, and clarity of value proposition — compare against top-performing profiles in the same role. (2) Audit the summary/about section for storytelling, keyword coverage, accomplishments, and a clear call to action. (3) Review each experience bullet for quantified achievements, action verbs, and relevance to target roles. (4) Analyze the skills section for alignment with recruiter search patterns and industry demand. (5) Check the profile photo, banner, featured section, and recommendations for completeness and professionalism. (6) Deliver a full optimization report with a score for each section, specific rewrites for underperforming areas, before-and-after comparisons, and a prioritized action plan ranked by recruiter visibility impact.`,heroOverlaySteps:[`Auditing your headline, summary, and experience for recruiter keyword alignment`,`Analyzing skills and endorsements against industry search patterns`,`Benchmarking your profile against top performers in your role`,`Optimization report with before-and-after rewrites — ready to apply`],generatingSteps:[`Visiting {url} to audit your headline, summary, experience, and skills`,`Designing an agent to benchmark your profile against recruiter search patterns`,`Configuring section-by-section scoring and rewrite pipelines`,`Setting up optimization report with before-and-after comparisons`],featureSectionTitle:`From LinkedIn profile to recruiter magnet`,featureCardTitles:[`Connects to your career stack`,`Outputs you can apply today`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Google Sheets, Notion, Gmail — Computer exports your optimized profile copy and action plan straight into the tools you already use.`,`Rewritten headline. Optimized summary. Stronger experience bullets. Skills realignment. Before-and-after comparisons ranked by recruiter visibility impact.`],capabilitySectionTitle:`Your profile strategist, on autopilot`,capabilitySectionSubtitle:`Paste your LinkedIn URL, get back a complete optimization playbook.`,capabilityCards:[{title:`Headline & Summary Audit`,description:`Computer can evaluate your headline and about section for keyword coverage, value clarity, and recruiter search alignment — and rewrite both with stronger positioning.`},{title:`Experience Optimization`,description:`Computer can review every experience bullet for quantified results, action verbs, and role relevance — then rewrite weak entries with measurable accomplishments.`},{title:`Recruiter Pattern Matching`,description:`Computer can analyze how recruiters search for your target role — keywords, title variations, skill filters — and show where your profile falls short.`},{title:`Connect Your Tools`,description:`Computer can export to Google Docs, Google Sheets, Notion, and Gmail — build workflows that keep your profile copy, outreach, and tracking in one place.`},{title:`Remembers Your Goals`,description:`Computer can remember your target roles, industries, career history, and past audits — so every optimization builds on what came before.`},{title:`Profile Change Alerts`,description:`Computer can monitor your LinkedIn profile weekly — and alert you when keyword trends shift, new skills emerge, or sections need refreshing.`}]});export{t as default};
